mapper.select:
SELECT id, organization_id, actor_type, actor_member_id, actor_identifier, action, target_type, target_id, result, ip_address::text AS ip_address, user_agent, request_id, metadata, occurred_at FROM audit_event WHERE organization_id = #{organizationId}
AND ( lower(actor_identifier) LIKE lower(concat('%', #{keyword}, '%')) OR lower(action) LIKE lower(concat('%', #{keyword}, '%')) OR lower(target_type) LIKE lower(concat('%', #{keyword}, '%')) OR lower(target_id) LIKE lower(concat('%', #{keyword}, '%')) OR lower(coalesce(request_id, '')) LIKE lower(concat('%', #{keyword}, '%')) )
AND action = #{action}
AND target_type = #{targetType}
AND result = #{result}
ORDER BY occurred_at DESC, id DESC
